import { createHmac } from "node:crypto";
import { acknowledgeTask, isTaskDispatch, skipped, turnStarted, } from "../../internal/channel-dispatch.js";
import { continuationSource, mintClaim } from "../../internal/continuation-identity.js";
import { isRecord } from "../../internal/is-record.js";
import { hmacSignatureMatchesAny, parseHmacSecrets } from "../../internal/hmac-secret-values.js";
import { bindLocalIngressSend } from "../../internal/local-ingress.js";
import { resolveWebhookSecretCheck } from "../../internal/named-webhook-secret.js";
import { defaultPagerDutyIncidentDispatch, defaultPagerDutyIncidentMessage, defaultPagerDutyTitle, } from "./defaults.js";
import { isPagerDutyIncidentLifecycleEvent, PAGERDUTY_CHANNEL_KIND, PAGERDUTY_NOTE_EVENTS, PAGERDUTY_RESPONDER_EVENTS, } from "./events.js";
import { asNonEmptyString, pagerDutyAccountSubdomain, pagerDutyEventIncident, pagerDutyEventRecord, pagerDutyIncidentFromData, pagerDutyNoteFromData, pagerDutyReference, pagerDutyResponderFromData, } from "./payload.js";
import { pagerDutyChannelClient } from "./api.js";
import { resolvePagerDutySecret } from "./secrets.js";
import { resolvePagerDutySelfUserIds } from "./self-user.js";
import { pagerDutyChannelStateForEvent } from "./state.js";
import { storedJson } from "../../internal/json-value.js";
/** Env var / deployment secret an omitted `webhookSecret` falls back to. */
export const PAGERDUTY_WEBHOOK_SECRET_ENV = "PAGERDUTY_WEBHOOK_SECRET";
/** Header PagerDuty signs v3 deliveries with: `v1=<hex>[,v1=<hex>…]`. */
export const PAGERDUTY_SIGNATURE_HEADER = "x-pagerduty-signature";
export const PAGERDUTY_SIGNATURE_PREFIX = "v1=";
/** Separator between signatures while a subscription's secret rotates. */
export const PAGERDUTY_SIGNATURE_SEPARATOR = ",";
/**
 * The secret's value for the handler's own signature check, read now: an
 * omitted field names `PAGERDUTY_WEBHOOK_SECRET` (hosted, the addressed
 * installation's secret), and an authored name never falls back to it.
 */
export function resolvePagerDutyWebhookSecret(options) {
    return resolvePagerDutySecret(options.webhookSecret, PAGERDUTY_WEBHOOK_SECRET_ENV);
}
/** One `X-PagerDuty-Signature` entry for a raw body: `v1=<hex>`. */
export function signPagerDutyWebhookBody(input) {
    return `${PAGERDUTY_SIGNATURE_PREFIX}${createHmac("sha256", input.secret).update(input.rawBody).digest("hex")}`;
}
/**
 * True when any `v1=` entry in the header is the body's HMAC-SHA256 under
 * any secret `secret` holds. `secret` is the named secret's value: one
 * signing secret, or one per line when several subscriptions sign the
 * route. Every (secret, entry) pair is compared in constant time with no
 * early exit; malformed entries never match, and a missing header is a
 * plain `false`.
 */
export function verifyPagerDutyWebhookSignature(input) {
    const parsed = parseHmacSecrets(input.secret);
    if (input.signatureHeader === null || input.signatureHeader === undefined || !parsed.ok) {
        return false;
    }
    return hmacSignatureMatchesAny({
        body: input.rawBody,
        presented: input.signatureHeader,
        secrets: parsed.secrets,
        prefix: PAGERDUTY_SIGNATURE_PREFIX,
        separator: PAGERDUTY_SIGNATURE_SEPARATOR,
    });
}
/**
 * True when the event is the agent's own action echoed back: its `agent`
 * is a PagerDuty user the agent acts as. Service integrations and
 * PagerDuty itself never count, so an alert the agent's own monitor opened
 * still dispatches.
 */
export function isPagerDutySelfEcho(ctx, selfUserIds) {
    const agent = ctx.agent;
    if (agent === undefined || selfUserIds.size === 0) {
        return false;
    }
    if (agent.type !== undefined && agent.type !== "user_reference" && agent.type !== "user") {
        return false;
    }
    return selfUserIds.has(agent.id);
}
/**
 * Accept a raw v3 body. The event type comes from the signed body's
 * `event.event_type`, never from a header, so a captured delivery cannot be
 * re-dispatched as another event.
 */
export function parsePagerDutyWebhookPayload(payload) {
    const event = pagerDutyEventRecord(payload);
    const eventType = asNonEmptyString(event?.event_type);
    if (event === undefined || eventType === undefined) {
        return null;
    }
    if (!isRecord(payload)) {
        return null;
    }
    return { eventType, payload };
}
export function parsePagerDutyEventContext(delivery) {
    const event = pagerDutyEventRecord(delivery.payload);
    const eventId = asNonEmptyString(event?.id);
    if (event === undefined || eventId === undefined) {
        return null;
    }
    const incident = pagerDutyEventIncident(event);
    return {
        deliveryId: delivery.deliveryId,
        eventId,
        eventType: delivery.eventType,
        resourceType: asNonEmptyString(event.resource_type),
        occurredAt: asNonEmptyString(event.occurred_at),
        agent: pagerDutyReference(event.agent),
        incidentId: incident?.id,
        incidentKey: incident?.incidentKey,
        accountSubdomain: pagerDutyAccountSubdomain(event),
        payload: event,
    };
}
function invalidPayload(error) {
    return Response.json({ ok: false, error }, { status: 400 });
}
async function applyDispatch(input) {
    const extra = { event: input.ctx.eventType };
    if (input.dispatch === null) {
        return skipped("not_dispatched", extra);
    }
    if (isTaskDispatch(input.dispatch)) {
        return acknowledgeTask(input.args, PAGERDUTY_CHANNEL_KIND, input.dispatch, extra);
    }
    const ctx = input.ctx;
    const state = pagerDutyChannelStateForEvent({
        eventType: ctx.eventType,
        eventId: ctx.eventId,
        incidentId: ctx.incidentId,
        incidentNumber: input.incidentNumber,
        incidentKey: ctx.incidentKey,
        serviceId: input.serviceId,
        deliveryId: ctx.deliveryId,
        occurredAt: ctx.occurredAt,
    });
    // v1 agents (omitted continuation resolves to `none/v1`) keep one
    // engine-minted conversation per incident; v2 takes the CP stamp.
    const engineToken = continuationSource(input.options.continuation, PAGERDUTY_CHANNEL_KIND) === "engine" &&
        ctx.incidentId !== undefined
        ? mintClaim({
            type: "pagerduty-incident",
            resource: { incidentId: ctx.incidentId },
        }).slice("cont:".length)
        : undefined;
    const turn = {
        auth: input.dispatch.auth,
        title: input.dispatch.title ?? input.title,
        state: storedJson(state),
        refreshState: storedJson(state),
    };
    if (engineToken !== undefined) {
        turn.continuationToken = engineToken;
    }
    if (input.options.cloud !== undefined) {
        turn.cloud = input.options.cloud;
    }
    const session = await input.args.send([input.dispatch.message ?? input.message, ...(input.dispatch.context ?? [])].join("\n"), turn);
    return turnStarted(session);
}
/**
 * Run the authored hooks for one verified PagerDuty delivery and `send()`
 * the turn. Callers own delivery auth: the HTTP route verifies
 * `X-PagerDuty-Signature`; hosted admission arrives verified. The v2
 * mailbox is stamped upstream (local CP or hosted ingress), never here.
 */
export async function dispatchPagerDutyWebhook(input) {
    const parsed = parsePagerDutyEventContext(input.delivery);
    if (parsed === null) {
        return invalidPayload("invalid_pagerduty_payload");
    }
    const args = input.args;
    const ctx = {
        ...parsed,
        pagerduty: pagerDutyChannelClient(input.options),
        host: args.host,
        artifacts: args.artifacts,
        send: args.send,
    };
    const eventType = ctx.eventType;
    if (eventType === "pagey.ping") {
        return skipped("ping");
    }
    if (isPagerDutySelfEcho(ctx, await resolvePagerDutySelfUserIds({ options: input.options }))) {
        return skipped("self_echo", { event: eventType, agent: ctx.agent?.id });
    }
    const data = ctx.payload.data;
    if (isPagerDutyIncidentLifecycleEvent(eventType)) {
        const incident = pagerDutyIncidentFromData(data);
        if (incident === undefined) {
            return invalidPayload("invalid_pagerduty_incident_payload");
        }
        const event = { eventType, action: eventType.slice("incident.".length), incident };
        const dispatch = input.options.onIncident === undefined
            ? defaultPagerDutyIncidentDispatch(ctx, event)
            : await input.options.onIncident(ctx, event);
        return applyDispatch({
            options: input.options,
            args,
            ctx,
            dispatch,
            message: defaultPagerDutyIncidentMessage(ctx, event),
            title: defaultPagerDutyTitle(ctx, incident),
            incidentNumber: incident.number,
            serviceId: incident.service?.id,
        });
    }
    if (PAGERDUTY_NOTE_EVENTS.includes(eventType)) {
        if (input.options.onNote === undefined) {
            return skipped("no_handler", { event: eventType });
        }
        const note = pagerDutyNoteFromData(data);
        if (note === undefined) {
            return invalidPayload("invalid_pagerduty_note_payload");
        }
        return applyDispatch({
            options: input.options,
            args,
            ctx,
            dispatch: await input.options.onNote(ctx, note),
            message: `PagerDuty note on incident ${note.incident.id}:\n${note.content}`,
            title: defaultPagerDutyTitle(ctx),
        });
    }
    if (PAGERDUTY_RESPONDER_EVENTS.includes(eventType)) {
        if (input.options.onResponder === undefined) {
            return skipped("no_handler", { event: eventType });
        }
        const responder = pagerDutyResponderFromData(eventType, data);
        if (responder === undefined) {
            return invalidPayload("invalid_pagerduty_responder_payload");
        }
        return applyDispatch({
            options: input.options,
            args,
            ctx,
            dispatch: await input.options.onResponder(ctx, responder),
            message: `PagerDuty ${eventType} on incident ${responder.incident.id}`,
            title: defaultPagerDutyTitle(ctx),
        });
    }
    if (input.options.onEvent === undefined) {
        return skipped("unsupported_event", { event: eventType });
    }
    return applyDispatch({
        options: input.options,
        args,
        ctx,
        dispatch: await input.options.onEvent(ctx, { eventType, data }),
        message: `PagerDuty ${eventType} event`,
        title: defaultPagerDutyTitle(ctx),
    });
}
/**
 * HTTP entry for one agent's PagerDuty channel: the `X-PagerDuty-Signature`
 * check when a secret is configured, then {@link dispatchPagerDutyWebhook}.
 * Without a secret the route auth owns admission (`serve --dev` admits
 * loopback only; production stays loopback-strict).
 */
export async function handlePagerDutyWebhookRequest(input) {
    const bodyText = await input.request.text();
    const check = resolveWebhookSecretCheck(input.options.webhookSecret, resolvePagerDutyWebhookSecret(input.options));
    if (check !== "none") {
        const verified = check !== "missing" &&
            verifyPagerDutyWebhookSignature({
                rawBody: bodyText,
                signatureHeader: input.request.headers.get(PAGERDUTY_SIGNATURE_HEADER),
                secret: check.secret,
            });
        if (!verified) {
            return Response.json({ ok: false, error: "invalid_signature" }, { status: 401 });
        }
    }
    let payload;
    try {
        payload = JSON.parse(bodyText);
    }
    catch {
        return Response.json({ ok: false, error: "invalid_json" }, { status: 400 });
    }
    const delivery = parsePagerDutyWebhookPayload(payload);
    if (delivery === null) {
        return invalidPayload("invalid_pagerduty_payload");
    }
    delivery.deliveryId = input.request.headers.get("x-webhook-id") ?? undefined;
    return dispatchPagerDutyWebhook({
        options: input.options,
        delivery,
        args: bindLocalIngressSend(input.args, {
            identity: input.options.continuation,
            kind: PAGERDUTY_CHANNEL_KIND,
            eventType: delivery.eventType,
            payload: delivery.payload,
        }),
    });
}
